  margin: auto;
  text-decoration: underline;
}

p{
  padding-top: 0.4cm;
}

.info:nth-of-type(1){
  margin-top: 0.9cm;
}
.info{
  margin-top: 0.3cm;
 position: relative;
}

ol{
    padding-left: 1cm;
    list-style: none;
}
ol li{
    padding: 0 0.3cm;
}
pre{
    font-size: 1rem;
    padding: 2px;
    background: none !important;
    border:  none !important;
    height: auto !important;
    text-wrap: wrap;
    font-family: sans-serif !important;
    font-weight: 500 !important;
    margin: 0 !important;
}

